<?php
/** Opt-in source-backup identity restore; schema isolated, media extraction deliberately excluded. */
if(PHP_SAPI!=='cli')exit(2);require dirname(__DIR__).'/resources/require.php';$source=getenv('OPENWEB_PRIVATE_BACKUP');if(!$source)exit(2);
$db=$database->db;$schema='identity115_'.bin2hex(random_bytes(6));$n=0;$prior=$_SESSION;
$ok=static function($v,$why)use(&$n){if(!$v)throw new RuntimeException($why);$n++;};$q=static function($sql,$p=[])use($db){$s=$db->prepare($sql);$s->execute($p);return$s;};
try{
$db->exec('create schema '.$schema);$db->exec('set search_path to '.$schema.',public');foreach(['v_menu_items','v_menu_languages','v_domains','v_extensions','v_voicemails','v_gateways','v_ring_groups','v_ring_group_destinations','v_destinations','v_dialplans','v_dialplan_details','v_call_center_agents','v_call_center_queues','v_call_center_tiers','v_ivr_menus','v_ivr_menu_options','v_devices','v_device_lines','v_device_keys','v_contacts','v_contact_phones','v_recordings','v_voicemail_messages','v_voicemail_greetings']as$t)$db->exec('create table '.$t.'(like public.'.$t.' including all)');$db->exec(file_get_contents(dirname(__DIR__).'/app/pbx_setup/resources/restore.sql'));
$plan=threecx_backup::analyze($source);$domain=uuid();$realm='identity115-'.bin2hex(random_bytes(5)).'.invalid';$db->beginTransaction();$q('insert into v_domains(domain_uuid,domain_name,domain_enabled)values(?,?,true)',[$domain,$realm]);(new pbx_setup_provisioner($db))->apply($domain,$realm,$plan);$r=new pbx_v20_restore($db);$r->apply($domain,$realm,$plan);$db->commit();$c=json_decode($q('select config from v_pbx_restore where domain_uuid=?',[$domain])->fetchColumn(),true);$key=file_get_contents(pbx_paths::key());
foreach($plan['users']as$u){$v=$c['users'][$u['number']];$native=$q('select extension,password,number_alias,effective_caller_id_number from v_extensions where domain_uuid=? and extension_uuid=?',[$domain,$v['extension_uuid']])->fetch(PDO::FETCH_ASSOC);$ok($native['extension']===$u['auth_id'],'Authentication ID changed');$ok($native['effective_caller_id_number']===$u['number']&&isset($c['users'][$u['number']])&&$native['number_alias']===null,'Extension SIP address changed');$ok(hash_equals($u['password'],$native['password']),'Source password bytes changed');$ok(hash_equals($v['restore_identity_hmac'],pbx_phone_migration::identityProof($domain,$u['number'],$u['auth_id'],$u['password'],$key)),'Original backup identity proof mismatch');}
$ok(count($c['ring_groups'])===count($plan['v20']['ring_groups']),'Source ring group lost');$ok(count($c['queues'])===count($plan['v20']['queues']),'Source queue lost');$ok(count($c['inbound_rules'])===count($plan['v20']['inbound_rules']),'Source incoming route lost');$ok(count($c['outbound_rules'])===count($plan['v20']['outbound_rules']),'Source outgoing route lost');
$_SESSION=['authorized'=>true,'user_uuid'=>uuid(),'domain_uuid'=>$domain,'domain_name'=>$realm];$migration=new pbx_phone_migration($db);$proof=$migration->inspectBackup($source);$ok($proof['matched']===count($plan['users'])&&!$proof['issues'],'Read-only backup comparison failed');$ok(!$proof['credentials_changed']&&!$proof['settings_reapplied'],'Source comparison rewrote calling settings');$after=json_decode($q('select config from v_pbx_restore where domain_uuid=?',[$domain])->fetchColumn(),true);$ok($c===$after,'Read-only identity comparison changed restored call settings');
echo json_encode(['passed'=>true,'checks'=>$n,'original_user_tuples'=>count($plan['users']),'ring_groups'=>count($c['ring_groups']),'queues'=>count($c['queues']),'media_extraction_tested'=>false,'physical_phones_tested'=>false],JSON_THROW_ON_ERROR)."\n";
}finally{if($db->inTransaction())$db->rollBack();$db->exec('set search_path to public');$db->exec('drop schema if exists '.$schema.' cascade');$_SESSION=$prior;}
